import * as fs from 'fs';

console.log("Checking environment variables:");
console.log("APIDECK_APP_ID:", process.env.APIDECK_APP_ID);
console.log("APIDECK_API_KEY:", process.env.APIDECK_API_KEY ? "PRESENT (length: " + process.env.APIDECK_API_KEY.length + ")" : "MISSING");
console.log("APIDECK_CONSUMER_ID:", process.env.APIDECK_CONSUMER_ID);
console.log("APIDECK_FILE_STORAGE_DRIVE_NAME:", process.env.APIDECK_FILE_STORAGE_DRIVE_NAME);

let runId = "";
try {
  runId = fs.readFileSync('/logs/artifacts/run-id', 'utf8').trim();
  console.log("run-id from file:", runId);
} catch (e) {
  console.log("Failed to read run-id file:", e);
}

import { Apideck } from "@apideck/unify";

async function main() {
  const apideck = new Apideck({
    apiKey: process.env.APIDECK_API_KEY,
    consumerId: process.env.APIDECK_CONSUMER_ID,
    appId: process.env.APIDECK_APP_ID,
  });

  console.log("Listing drives...");
  try {
    const response = await apideck.fileStorage.drives.list({
      serviceId: "onedrive",
    });

    console.log("Response keys:", Object.keys(response));
    if (response.getDrivesResponse) {
      console.log("Drives count:", response.getDrivesResponse.data.length);
      for (const drive of response.getDrivesResponse.data) {
        console.log(`Drive: ID=${drive.id}, Name=${drive.name}`);
      }
    } else {
      console.log("No getDrivesResponse found in response.");
    }

    // Test iteration
    console.log("Testing page iteration...");
    for await (const page of response) {
      if (page.getDrivesResponse) {
        console.log("Page drives count:", page.getDrivesResponse.data.length);
        for (const drive of page.getDrivesResponse.data) {
          console.log(`Page Drive: ID=${drive.id}, Name=${drive.name}`);
        }
      }
    }
  } catch (error) {
    console.error("Error listing drives:", error);
  }
}

main();

import { Apideck } from "@apideck/unify";
import * as fs from "fs";

async function main() {
  const apideck = new Apideck({
    apiKey: process.env.APIDECK_API_KEY,
    consumerId: process.env.APIDECK_CONSUMER_ID,
    appId: process.env.APIDECK_APP_ID,
  });

  const driveName = process.env.APIDECK_FILE_STORAGE_DRIVE_NAME;
  if (!driveName) {
    throw new Error("APIDECK_FILE_STORAGE_DRIVE_NAME is not set");
  }

  const runId = fs.readFileSync('/logs/artifacts/run-id', 'utf8').trim();
  console.log(`Using runId: ${runId}`);

  console.log("Listing drives...");
  const drivesResponse = await apideck.fileStorage.drives.list({
    serviceId: "onedrive",
  });

  let driveId: string | undefined;
  for await (const page of drivesResponse) {
    if (page.getDrivesResponse) {
      for (const drive of page.getDrivesResponse.data) {
        if (drive.name === driveName) {
          driveId = drive.id;
          break;
        }
      }
    }
    if (driveId) {
      break;
    }
  }

  if (!driveId) {
    throw new Error(`Drive with name "${driveName}" not found`);
  }

  console.log(`Resolved driveId: ${driveId}`);

  console.log("Creating parent folder...");
  try {
    const parentResponse = await apideck.fileStorage.folders.create({
      serviceId: "onedrive",
      createFolderRequest: {
        name: `apideck-parent-${runId}`,
        parentFolderId: "root",
        driveId: driveId,
      }
    });

    console.log("Parent folder create response:", JSON.stringify(parentResponse, null, 2));
  } catch (error) {
    console.error("Error creating parent folder:", error);
  }
}

main();

